import { BaseComponent } from '../../base/base-component';
import * as template from './template';
import { controller } from './controller';
import { createActions } from './actions';

export interface NavigationManagerState {
    currentPage: string;
    user: any | null;
}

export class NavigationManager extends BaseComponent {
    static override observedAttributes = ['current-page', 'user'];

    constructor() {
        super();
        this._templateMethods = template;
        this.state = {
            currentPage: 'componentA',
            user: null
        };
    }

    override async _componentReady(): Promise<void> {
        this._controller = await controller(this);
        this._actions = await createActions(this) as any;
        await this.fullRender(this.state);
    }


    override async _componentAttributeChanged(name: string, oldValue: string | null, newValue: string | null): Promise<void> {
        if (name === 'current-page' && newValue !== oldValue) {
            this.state.currentPage = newValue as string;
            await this.fullRender(this.state);
        }
    }

    async navigateTo(page: string): Promise<void> {
        if (this.state.currentPage !== page) {
            this.state.currentPage = page;
            await this.fullRender(this.state);
            console.log('🧭 Navigated to:', page);
        }
    }

    async setUser(user: any): Promise<void> {
        this.state.user = user;
        await this.fullRender(this.state);
        console.log('👤 User updated:', user?.username || 'null');
    }

    // Публичный метод для выхода (можно вызывать из других компонентов)
    async logout(): Promise<void> {
        await (this._actions as any).handleLogout();
    }

    // Добавляем недостающий метод handleLogout
    async handleLogout(): Promise<void> {
        await (this._actions as any).handleLogout();
    }

    // Новый метод для остановки всех компонентов
    async stopAllComponents(): Promise<void> {
        await (this._actions as any).stopAllComponents();
    }
}

if (!customElements.get('navigation-manager')) {
    customElements.define('navigation-manager', NavigationManager);
}