import { NavigationManager } from '..';

export interface EventListener {
    element: EventTarget;
    event: string;
    handler: EventListenerOrEventListenerObject;
}

export const controller = (context: NavigationManager) => {
    let eventListeners: EventListener[] = [];

    const addEventListener = (element: EventTarget, event: string, handler: EventListenerOrEventListenerObject): void => {
        element.addEventListener(event, handler);
        eventListeners.push({ element, event, handler });
    };

    return {
        async init(): Promise<void> {
            // Обработчик кликов для кнопки выхода
            addEventListener(context.shadowRoot!, 'click', (e: Event) => {
                const target = e.target as HTMLElement;
                if (target.classList.contains('logout-btn')) {
                    (context as any)._actions.handleLogout();
                }
            });

            // Обработчики для навигационных событий
            addEventListener(context.shadowRoot!, 'component-navigate', (e: Event) => {
                const customEvent = e as CustomEvent;
                const { page } = customEvent.detail;
                context.navigateTo(page);
            });

            addEventListener(context.shadowRoot!, 'user-updated', (e: Event) => {
                const customEvent = e as CustomEvent;
                const { user } = customEvent.detail;
                context.setUser(user);
            });

            // Обработчик для глобальных событий авторизации
            addEventListener(window, 'storage', (e: Event) => {
                const storageEvent = e as StorageEvent;
                if (storageEvent.key === 'guss-user') {
                    (context as any)._actions.handleStorageChange(storageEvent);
                }
            });

            // Обработчик для сообщений от других компонентов
            addEventListener(context, 'post-message', (e: Event) => {
                const customEvent = e as CustomEvent;
                (context as any)._actions.handlePostMessage(customEvent.detail);
            });

            // Обработчик клавиши Escape для выхода
            addEventListener(document, 'keydown', (e: Event) => {
                const keyboardEvent = e as KeyboardEvent;
                if (keyboardEvent.key === 'Escape' && (context as any).state.user) {
                    (context as any)._actions.handleLogout();
                }
            });

            // Обработчик для глобальных событий выхода
            addEventListener(window, 'global-logout', () => {
                (context as any)._actions.handleLogout();
            });
        },

        async destroy(): Promise<void> {
            eventListeners.forEach(({ element, event, handler }) => {
                element.removeEventListener(event, handler);
            });
            eventListeners = [];
        }
    };
};