import './components/navigation-manager';
import './components/test-component-a';
import './components/test-component-b';

interface AppContext {
    [key: string]: any[];
}

interface ComponentConfig {
    component: string;
    id: string;
    slot: string;
    attributes?: Record<string, string>;
}

const components: Record<string, any> = {};
let root: Element | undefined;
const context: AppContext = {};

// Интерфейс для виртуального CSS модуля
interface VirtualCSSModule {
    getCSSForComponent: (componentName: string) => string | null;
    getCSSByPath?: (filePath: string) => string | null;
    getAllCSS?: () => string;
    injectCSS?: () => void;
}

let cssModule: VirtualCSSModule | false = false;

// Функция для асинхронной загрузки CSS модуля
async function loadCSSModule(): Promise<void> {
    try {
        cssModule = await import('virtual:css') as VirtualCSSModule;
    } catch (e) {
        // console.warn('virtual:css не загружен');
    }
}

// Инициализация CSS модуля
let cssModuleInitialized = false;
async function ensureCSSModule(): Promise<void> {
    if (!cssModuleInitialized) {
        await loadCSSModule();
        cssModuleInitialized = true;
    }
}

// Создаем app отдельно от window.onload
const appInit = async (): Promise<any> => {
    // Убеждаемся, что CSS модуль загружен
    await ensureCSSModule();

    if (cssModule && cssModule.injectCSS) {
        cssModule.injectCSS();
    }

    const componentConfigs: ComponentConfig[] = [
        {
            component: 'test-component-a',
            id: 'test-component-a-1',
            slot: 'test-components'
        },
        {
            component: 'test-component-b',
            id: 'test-component-b-1',
            slot: 'test-components'
        },
        {
            component: 'navigation-manager',
            id: 'navigation-manager',
            slot: 'navigation'
        }
    ];

    for (const item of componentConfigs) {
        const isAttribute = item.hasOwnProperty('attributes');

        if (!context[item.component]) {
            context[item.component] = [];
        }

        const element = document.createElement(item.component);
        element.setAttribute('id', item.id);
        element.setAttribute('slot', item.slot);

        if (isAttribute && item.attributes) {
            for (const key in item.attributes) {
                const value = item.attributes[key];
                if (typeof value === 'string') {
                    element.setAttribute(key, value);
                }
            }
        }

        // Добавляем элемент в DOM перед вызовом connectedCallback
        if (!document.body.querySelector(`${item.component}[id="${item.id}"]`)) {
            document.body.appendChild(element);
        }

        // Ждем готовности компонента
        if ((element as any).connectedCallback) {
            await (element as any).connectedCallback();
        }

        if (context[item.component]) {
            context[item.component]!.push({ element });
        }

        if (!components[item.component]) {
            components[item.component] = {
                id: {
                    [item.id]: element
                }
            };
            root = root ? root : element;
        } else if (!components[item.component].id[item.id]) {
            components[item.component].id[item.id] = element;
            root = root ? root : element;
        } else {
            console.log('item', item);
            console.error('Duplicate component ID');
        }
    }

    setTimeout(async () => {
        document.documentElement.classList.add('visible');
    }, 1000);

    // Инициализируем взаимодействие между компонентами после загрузки всех
    await initializeComponentInteractions();

    console.log('✅ All components initialized successfully');
    console.log('📊 Loaded components:', Object.keys(components));
    console.log('componentConfigs', components);
    return components;
};

// Инициализируем app
const app = appInit();

// Устанавливаем onload
window.onload = async () => {
    await app;
};

// Исправляем доступ к app через then
app.then(() => {
    globalThis.startTime = Date.now();
    globalThis.NODE_PORT = 6832;
});

/**
 * Инициализирует взаимодействие между компонентами после загрузки
 */
async function initializeComponentInteractions(): Promise<void> {
    try {
        // Ждем определения компонентов
        await Promise.all([
            customElements.whenDefined('test-component-a'),
            customElements.whenDefined('test-component-b')
        ]);

        // Альтернативный подход - получаем элементы из DOM
        const componentAElement = document.querySelector('test-component-a#test-component-a-1') as any;
        const componentBElement = document.querySelector('test-component-b#test-component-b-1') as any;

        if (componentAElement && componentBElement) {
            console.log('🔗 Test components linked successfully');

            setTimeout(async () => {
                if (componentAElement.postMessage) {
                    const result = await componentAElement.postMessage({
                        type: 'ADD_ITEM',
                        data: { item: 'Элемент из Component B' },
                        source: 'test-component-b'
                    });
                    if (result.success) {
                        console.log('📨 Message from Component B to Component A delivered successfully');
                    }
                }
            }, 1000);
        }

        // Проверяем навигационный менеджер
        const navManager = document.querySelector('navigation-manager#navigation-manager') as any;
        if (navManager) {
            console.log('🧭 Navigation manager initialized');
        }

    } catch (error) {
        console.warn('⚠️ Component interactions initialization warning:', error);
    }
}

/**
 * Глобальная функция для тестирования компонентов
 */
(window as any).testComponents = async (): Promise<void> => {
    try {
        const componentAElement = document.querySelector('test-component-a#test-component-a-1') as any;
        const componentBElement = document.querySelector('test-component-b#test-component-b-1') as any;

        if (componentAElement) {
            console.log('🧪 Testing Component A:');
            const result = await componentAElement.postMessage({
                type: 'GET_STATE',
                source: 'test-script'
            });
            console.log('Component A state:', result);
        }

        if (componentBElement) {
            console.log('🧪 Testing Component B:');
            const result = await componentBElement.postMessage({
                type: 'GET_INFO',
                source: 'test-script'
            });
            console.log('Component B info:', result);
        }

        console.log('✅ Component tests completed');
    } catch (error) {
        console.error('❌ Component tests failed:', error);
    }
};

/**
 * Глобальная функция для получения информации о загруженных компонентах
 */
(window as any).getComponentInfo = (): void => {
    console.log('📋 Loaded components:');
    Object.keys(components).forEach(componentName => {
        const instances = Object.keys(components[componentName].id);
        console.log(`  - ${componentName}: ${instances.length} instance(s) - ${instances.join(', ')}`);
    });

    console.log('🔧 Available test commands:');
    console.log('   testComponents() - запустить тесты компонентов');
    console.log('   getComponentInfo() - показать информацию о компонентах');
};

// Автоматически показываем информацию о компонентах при загрузке
setTimeout(() => {
    (window as any).getComponentInfo();
}, 500);

export { app };