import { TestComponentBState } from '..';

export function defaultTemplate({ state = {} }: { state: Partial<TestComponentBState>; context: any }): string {
    const {
        title = 'Test Component B',
        description = 'Это второй тестовый компонент с расширенными функциями',
        rating = 4,
        features = [],
        isActive = true
    } = state;

    const generateStars = (rating: number): string => {
        return '★'.repeat(rating) + '☆'.repeat(5 - rating);
    };

    return `
    <div class="test-component-b">
      <div class="header">
        <h2 class="title">${title}</h2>
        <div class="status ${isActive ? 'success' : 'danger'}">${isActive ? 'Активен' : 'Неактивен'}</div>
      </div>
      
      <p class="description">${description}</p>
      
      <div class="rating-section">
        <h3>Рейтинг:</h3>
        <div class="rating-controls">
          <div class="rating-stars">${generateStars(rating)}</div>
          <div class="star-selector">
            ${[1, 2, 3, 4, 5].map(star => `
              <button class="star yato-button secondary" data-rating="${star}" type="button">${star}★</button>
            `).join('')}
          </div>
        </div>
      </div>

      <div class="features-section">
        <h3>Функции (${features.length}):</h3>
        <div class="features-list">
          ${features.length ? `
            <ul>
              ${features.map((feature) => `
                <li class="feature-item">
                  <span class="feature-icon">⚡</span>
                  <span class="feature-text">${feature}</span>
                </li>
              `).join('')}
            </ul>
          ` : '<p class="no-features">Функции не добавлены</p>'}
        </div>
        
        <form class="feature-form">
          <input type="text" name="feature" placeholder="Добавить новую функцию" required>
          <button type="submit" class="yato-button primary">Добавить</button>
        </form>
      </div>

      <div class="controls">
        <button class="btn-toggle yato-button ${isActive ? 'secondary' : 'primary'}" type="button">
          ${isActive ? 'Деактивировать' : 'Активировать'}
        </button>
        <button class="btn-add-feature yato-button secondary" type="button">Добавить функцию</button>
      </div>

      <div class="component-info">
        <small>Test Component B - компонент с рейтингом и функциями</small>
      </div>
    </div>
  `;
}