import { TestComponentB } from '..';

export interface EventListener {
    element: EventTarget;
    event: string;
    handler: EventListenerOrEventListenerObject;
}

export const controller = (context: TestComponentB) => {
    let eventListeners: EventListener[] = [];

    const addEventListener = (element: EventTarget, event: string, handler: EventListenerOrEventListenerObject): void => {
        element.addEventListener(event, handler);
        eventListeners.push({ element, event, handler });
    };

    return {
        async init(): Promise<void> {
            // Обработчик кликов
            addEventListener(context.shadowRoot!, 'click', (e: Event) => {
                const target = e.target as HTMLElement;

                if (target.classList.contains('btn-toggle')) {
                    (context as any)._actions.handleToggle();
                }

                if (target.classList.contains('btn-add-feature')) {
                    (context as any)._actions.handleAddFeature();
                }

                if (target.classList.contains('star')) {
                    const rating = parseInt(target.dataset.rating || '1');
                    (context as any)._actions.handleSetRating(rating);
                }

                if (target.classList.contains('feature-remove')) {
                    const index = parseInt(target.dataset.index || '0');
                    (context as any)._actions.handleRemoveFeature(index);
                }
            });

            // Обработчик для формы добавления фичи
            const form = context.shadowRoot!.querySelector('.feature-form');
            if (form) {
                addEventListener(form, 'submit', (e: Event) => {
                    e.preventDefault();
                    (context as any)._actions.handleFeatureSubmit(new FormData(form as HTMLFormElement));
                });
            }

            // Обработчик изменения темы
            addEventListener(document.documentElement, 'theme-changed', (e: Event) => {
                const customEvent = e as CustomEvent;
                (context as any)._actions.handleThemeChange(customEvent.detail.theme);
            });

            // Обработчик клавиатуры
            addEventListener(document, 'keydown', (e: Event) => {
                const keyboardEvent = e as KeyboardEvent;
                if (keyboardEvent.ctrlKey && keyboardEvent.key === 'r') {
                    keyboardEvent.preventDefault();
                    (context as any)._actions.handleReset();
                }
            });

            console.log('🎮 TestComponentB controller initialized');
        },

        async destroy(): Promise<void> {
            eventListeners.forEach(({ element, event, handler }) => {
                element.removeEventListener(event, handler);
            });
            eventListeners = [];
            console.log('🧹 TestComponentB controller destroyed');
        }
    };
};