export function defaultTemplate({ state = {} }: { state: Record<string, any>; context: any }): string {
    const pages: Record<string, string> = {
        'navigation-manager': '<navigation-manager id="navigation-manager-0"></navigation-manager>',
        'componentA': '<component-a id="component-b"></component-a>',
        'componentB': '<component-b id="component-b"></component-b>'
    };

    console.log('Navigation Manager State:', state);

    return `
    <div id="app-container">
      ${state.user ? `
        <div class="user-header">
          <div class="user-info">
            <span class="username">👤 ${state.user.username}</span>
            <span class="user-role">(${state.user.role})</span>
          </div>
          <button class="logout-btn" title="Выйти (Escape)">
            🚪 Выйти
          </button>
        </div>
      ` : ''}
      ${pages[state.currentPage] || pages.login}
    </div>
  `;
}

export function userHeaderTemplate({ state = {} }: { state: Record<string, any>; context: any }): string {
    if (!state.user) return '';

    return `
    <div class="user-header">
      <div class="user-info">
        <span class="username">👤 ${state.user.username}</span>
        <span class="user-role">${state.user.role}</span>
        ${state.user.email ? `<span class="user-email">${state.user.email}</span>` : ''}
      </div>
      <div class="user-actions">
        <button class="logout-btn" title="Выйти из системы">
          🚪 Выйти
        </button>
      </div>
    </div>
  `;
}

export function navigationTemplate({ state = {} }: { state: Record<string, any>; context: any }): string {
    const navigationItems = [
        { id: 'rounds-list', label: '📋 Список раундов', icon: '📋' },
        { id: 'dashboard', label: '📊 Дашборд', icon: '📊' },
        { id: 'settings', label: '⚙️ Настройки', icon: '⚙️' },
        { id: 'profile', label: '👤 Профиль', icon: '👤' }
    ];

    return `
    <nav class="main-navigation">
      <ul class="nav-list">
        ${navigationItems.map(item => `
          <li class="nav-item ${state.currentPage === item.id ? 'active' : ''}">
            <button class="nav-link" data-page="${item.id}">
              <span class="nav-icon">${item.icon}</span>
              <span class="nav-label">${item.label}</span>
            </button>
          </li>
        `).join('')}
      </ul>
    </nav>
  `;
}

export function errorTemplate({ state = {} }: { state: Record<string, any>; context: any }): string {
    return `
    <div class="error-container">
      <div class="error-content">
        <h2 class="error-title">❌ Ошибка</h2>
        <p class="error-message">${state.error || 'Произошла неизвестная ошибка'}</p>
        <button class="retry-btn">Повторить попытку</button>
      </div>
    </div>
  `;
}

export function loadingTemplate({ state }: { state: Record<string, any>; context: any }): string {
    return `
    <div class="loading-container">
      <div class="loading-spinner"></div>
      <p class="loading-text">${state.loadingText || 'Загрузка...'}</p>
    </div>
  `;
}