import { TestComponentB, TestComponentBState } from '..';

export async function createActions(context: TestComponentB) {
    return {
        handleToggle: handleToggle.bind(context),
        handleAddFeature: handleAddFeature.bind(context),
        handleSetRating: handleSetRating.bind(context),
        handleFeatureSubmit: handleFeatureSubmit.bind(context)
    };
}

async function handleToggle(this: TestComponentB): Promise<void> {
    (this.state as TestComponentBState).isActive = !(this.state as TestComponentBState).isActive;

    await this.updateElement({
        selector: '.status',
        value: (this.state as TestComponentBState).isActive ? 'Активен' : 'Неактивен',
        property: 'textContent'
    });

    await this.updateElement({
        selector: '.status',
        value: (this.state as TestComponentBState).isActive ? 'success' : 'danger',
        property: 'className',
        action: 'remove'
    });

    await this.updateElement({
        selector: '.status',
        value: `status ${(this.state as TestComponentBState).isActive ? 'success' : 'danger'}`,
        property: 'className',
        action: 'set'
    });
}

async function handleAddFeature(this: TestComponentB): Promise<void> {
    const newFeature = `Функция ${(this.state as TestComponentBState).features.length + 1}`;
    (this.state as TestComponentBState).features.push(newFeature);
    await this.fullRender(this.state);
}

async function handleSetRating(this: TestComponentB, rating: number): Promise<void> {
    (this.state as TestComponentBState).rating = rating;

    await this.updateElement({
        selector: '.rating-stars',
        value: generateStars(rating),
        property: 'innerHTML'
    });
}

async function handleFeatureSubmit(this: TestComponentB, formData: FormData): Promise<void> {
    const feature = formData.get('feature') as string;
    if (feature && feature.trim()) {
        (this.state as TestComponentBState).features.push(feature.trim());
        await this.fullRender(this.state);

        const form = this.shadowRoot!.querySelector('.feature-form') as HTMLFormElement;
        if (form) form.reset();
    }
}

// Вспомогательная функция для генерации звезд рейтинга
function generateStars(rating: number): string {
    return '★'.repeat(rating) + '☆'.repeat(5 - rating);
}