import { BaseComponent } from '../../base/base-component';
import * as template from './template';
import { controller } from './controller';
import { createActions } from './actions';

export interface TestComponentBState {
    title: string;
    description: string;
    rating: number;
    features: string[];
    isActive: boolean;
}

export class TestComponentB extends BaseComponent {
    static override observedAttributes = ['title', 'description', 'rating'];

    constructor() {
        super();
        this._templateMethods = template;
        this.state = {
            title: 'Test Component B',
            description: 'Это второй тестовый компонент с расширенными функциями',
            rating: 4,
            features: ['Функция 1', 'Функция 2', 'Функция 3'],
            isActive: true
        };
    }

    override async _componentReady(): Promise<void> {
        this._controller = await controller(this);
        this._actions = await createActions(this);
        await this.fullRender(this.state);
    }

    override async _componentAttributeChanged(name: string, _oldValue: string | null, newValue: string | null): Promise<void> {
        const attributeHandlers: Record<string, () => Promise<void>> = {
            'title': async () => {
                this.state.title = newValue || 'Test Component B';
                await this.updateElement({
                    selector: '.title',
                    value: this.state.title,
                    property: 'textContent'
                });
            },
            'description': async () => {
                this.state.description = newValue || '';
                await this.updateElement({
                    selector: '.description',
                    value: this.state.description,
                    property: 'textContent'
                });
            },
            'rating': async () => {
                const rating = parseInt(newValue || '4');
                this.state.rating = Math.max(1, Math.min(5, rating));
                await this.updateElement({
                    selector: '.rating-stars',
                    value: this.#generateStars(this.state.rating),
                    property: 'innerHTML'
                });
            }
        };

        if (attributeHandlers[name]) {
            await attributeHandlers[name]();
        }
    }

    override async postMessage(event: any): Promise<any> {
        try {
            switch (event.type) {
                case 'SET_RATING':
                    const rating = event.data?.rating;
                    if (rating >= 1 && rating <= 5) {
                        this.state.rating = rating;
                        await this.updateElement({
                            selector: '.rating-stars',
                            value: this.#generateStars(this.state.rating),
                            property: 'innerHTML'
                        });
                        return { success: true, rating: this.state.rating };
                    }
                    return { success: false, error: 'Rating must be between 1 and 5' };

                case 'TOGGLE_ACTIVE':
                    this.state.isActive = !this.state.isActive;
                    await this.updateElement({
                        selector: '.status',
                        value: this.state.isActive ? 'Активен' : 'Неактивен',
                        property: 'textContent'
                    });
                    await this.updateElement({
                        selector: '.status',
                        value: this.state.isActive ? 'success' : 'danger',
                        property: 'className',
                        action: 'remove'
                    });
                    await this.updateElement({
                        selector: '.status',
                        value: `status ${this.state.isActive ? 'success' : 'danger'}`,
                        property: 'className',
                        action: 'set'
                    });
                    return { success: true, isActive: this.state.isActive };

                case 'ADD_FEATURE':
                    const feature = event.data?.feature;
                    if (feature && typeof feature === 'string') {
                        (this.state as TestComponentBState).features.push(feature);
                        await this.fullRender(this.state);
                        return { success: true, features: (this.state as TestComponentBState).features };
                    }
                    return { success: false, error: 'Invalid feature' };

                case 'GET_INFO':
                    return {
                        success: true,
                        info: {
                            title: this.state.title,
                            rating: this.state.rating,
                            isActive: this.state.isActive,
                            featuresCount: (this.state as TestComponentBState).features.length
                        }
                    };

                default:
                    console.warn(`[TestComponentB] Неизвестный тип сообщения: ${event.type}`);
                    return { success: false, error: 'Unknown message type' };
            }
        } catch (error) {
            this.addError({
                componentName: this.constructor.name,
                source: 'postMessage',
                message: `Ошибка обработки сообщения ${event.type}`,
                details: error
            });
            return { success: false, error: (error as Error).message };
        }
    }

    #generateStars(rating: number): string {
        return '★'.repeat(rating) + '☆'.repeat(5 - rating);
    }

    override async _componentDisconnected(): Promise<void> {
        if (this._controller?.destroy) {
            await this._controller.destroy();
        }
    }
}

if (!customElements.get('test-component-b')) {
    customElements.define('test-component-b', TestComponentB);
}