import { TestComponentAState } from '..';

export function defaultTemplate({ state = {} }: { state: Partial<TestComponentAState>; context: any }): string {
    const { title = 'Test Component A', items = [], counter = 0 } = state;

    return `
    <div class="test-component-a">
      <h2 class="title">${title}</h2>
      <div class="counter">Счетчик: ${counter}</div>
      
      <div class="controls">
        <button class="btn-increment yato-button primary">Увеличить счетчик</button>
        <button class="btn-add yato-button secondary">Добавить элемент</button>
      </div>

      <form class="add-form">
        <input type="text" name="newItem" placeholder="Введите новый элемент" required>
        <button type="submit" class="yato-button primary">Добавить</button>
      </form>

      <div class="items-list">
        <h3>Список элементов (${items.length}):</h3>
        ${items.length ? `
          <ul>
            ${items.map((item, index) => `
              <li class="item">
                <span>${item}</span>
                <button class="btn-remove yato-button danger" data-index="${index}">×</button>
              </li>
            `).join('')}
          </ul>
        ` : '<p>Список пуст</p>'}
      </div>

      <div class="component-info">
        <small>Test Component A - демонстрационный компонент</small>
      </div>
    </div>
  `;
}

export function renderList({ state = {} }: { state: Partial<TestComponentAState>; context: any }): string {
    const { items = [] } = state;

    if (!items.length) return '<p>Список пуст</p>';

    return items.map((item, index) => `
    <div class="item">
      <span>${item}</span>
      <button class="btn-remove yato-button danger" data-index="${index}">×</button>
    </div>
  `).join('');
}

export function renderCounter({ state = {} }: { state: Partial<TestComponentAState>; context: any }): string {
    const { counter = 0 } = state;
    return `
    <div class="counter-section">
      <div class="counter-display">Текущее значение: ${counter}</div>
      <div class="counter-stats">
        <small>Четное: ${counter % 2 === 0 ? 'Да' : 'Нет'}</small>
        <small>Больше 10: ${counter > 10 ? 'Да' : 'Нет'}</small>
      </div>
    </div>
  `;
}